sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    // Skip if loading or no change
    if (isLoading || newValue == oldValue) {
        return;
    }

    console.log('=== SIMPLE AJAX TEST ===');
    console.log('Calling TradeBookUtils.testConnection...');

    var ajax = new GlideAjax('TradeBookUtils');
    ajax.addParam('sysparm_name', 'testConnection');

    ajax.getXMLAnswer(function(response) {
        console.log('Response received: "' + response + '"');
        console.log('Response type: ' + typeof response);
        console.log('Response length: ' + (response ? response.length : 'null'));

        if (response && response !== 'null' && response.trim() !== '') {
            g_form.showFieldMsg('stock_name', 'SUCCESS: ' + response, 'info');
        } else {
            g_form.showFieldMsg('stock_name', 'FAILED: Response is null/empty', 'error');
        }
    });
}
